// ARTBox: the build probes whether the host already provides strlcpy.
#if !defined(__BIONIC__) && !defined(__APPLE__) && !defined(ANDROID_HOST_MUSL) && \
    !defined(ARTBOX_SYSTEM_HAS_STRLCPY)

// ARTBox: glibc may obtain MINSIGSTKSZ from sysconf at runtime. Cache the
// validated size at first use so setup and teardown use the same value.
static size_t HostAltSignalStackSize() {
  static const size_t size = []() {
    size_t result = 0;
    CHECK(artbox::host_stack_size(MINSIGSTKSZ, 32 * KB, &result));
    return result;
  }();
  return size;
}
